from math import gcd

from linalg import ordered_sum


def reduced_fraction(numerator, denominator):
    if denominator == 0:
        return None
    divisor = gcd(abs(numerator), denominator)
    return numerator // divisor, denominator // divisor


def sum_fractions(values):
    numerator, denominator = 0, 1
    for next_numerator, next_denominator in values:
        numerator, denominator = reduced_fraction(
            numerator * next_denominator + next_numerator * denominator,
            denominator * next_denominator,
        )
    return numerator, denominator


def confusion_matrix(actual, predictions, class_count):
    matrix = [[0] * class_count for _ in range(class_count)]
    for expected, predicted in zip(actual, predictions):
        matrix[expected][predicted] += 1
    return matrix


def measures(actual, predictions, class_count):
    matrix = confusion_matrix(actual, predictions, class_count)
    support = [sum(row) for row in matrix]
    predicted_counts = [sum(row[k] for row in matrix) for k in range(class_count)]
    correct = sum(matrix[k][k] for k in range(class_count))
    count = len(actual)
    recalls = [reduced_fraction(matrix[k][k], support[k]) for k in range(class_count)]
    precisions = [
        reduced_fraction(matrix[k][k], predicted_counts[k]) for k in range(class_count)
    ]
    f1 = [
        reduced_fraction(2 * matrix[k][k], support[k] + predicted_counts[k])
        for k in range(class_count)
    ]
    recall_numerator, recall_denominator = sum_fractions(recalls)
    expected = sum(support[k] * predicted_counts[k] for k in range(class_count))
    macro_f1 = ordered_sum(
        (2 * matrix[k][k]) / (support[k] + predicted_counts[k])
        for k in range(class_count)
    ) / class_count
    return {
        "matrix": matrix,
        "support": support,
        "correct": correct,
        "accuracy": reduced_fraction(correct, count),
        "balanced_accuracy": reduced_fraction(recall_numerator, recall_denominator * class_count),
        "kappa": reduced_fraction(count * correct - expected, count * count - expected),
        "recall": recalls,
        "precision": precisions,
        "f1": f1,
        "macro_f1": macro_f1,
    }


def mcnemar(actual, predictions_a, predictions_b):
    b01 = 0
    b10 = 0
    for expected, predicted_a, predicted_b in zip(actual, predictions_a, predictions_b):
        correct_a = predicted_a == expected
        correct_b = predicted_b == expected
        if correct_a and not correct_b:
            b01 += 1
        elif correct_b and not correct_a:
            b10 += 1
    if b01 == b10:
        chi2 = 0.0
    else:
        difference = abs(b01 - b10) - 1
        chi2 = (difference * difference) / (b01 + b10)
    return b01, b10, chi2, chi2 > 3.841


class RandomGenerator:
    def __init__(self, seed):
        self.state = seed

    def draw(self):
        self.state = (48271 * self.state) % 2147483647
        return self.state

from collections import namedtuple
from math import exp, log, pi

from linalg import cholesky, log_determinant, ordered_sum, quadratic_form, zeros


MODEL_NAMES = ("NB", "LDA", "QDA")
Prediction = namedtuple(
    "Prediction", "predicted posterior log_posterior confidence decision"
)


def argmax(values):
    best = 0
    for index in range(1, len(values)):
        if values[index] > values[best]:
            best = index
    return best


def argmin(values):
    best = 0
    for index in range(1, len(values)):
        if values[index] < values[best]:
            best = index
    return best


class Statistics:
    def __init__(self, rows, features, class_count):
        self.row_count = len(rows)
        self.feature_count = len(features)
        groups = [[] for _ in range(class_count)]
        vectors = []
        for row in rows:
            vector = [row.values[j] for j in features]
            vectors.append(vector)
            groups[row.class_index].append(vector)
        self.counts = [len(group) for group in groups]
        self.means = [
            [ordered_sum(vector[j] for vector in group) / len(group)
             for j in range(self.feature_count)]
            for group in groups
        ]
        self.scatter = []
        for group, mean in zip(groups, self.means):
            scatter = zeros(self.feature_count)
            for a in range(self.feature_count):
                for b in range(self.feature_count):
                    scatter[a][b] = ordered_sum(
                        (vector[a] - mean[a]) * (vector[b] - mean[b])
                        for vector in group
                    )
            self.scatter.append(scatter)
        self.center = [
            ordered_sum(vector[j] for vector in vectors) / self.row_count
            for j in range(self.feature_count)
        ]
        self.variances = [
            ordered_sum(
                (vector[j] - self.center[j]) * (vector[j] - self.center[j])
                for vector in vectors
            ) / self.row_count
            for j in range(self.feature_count)
        ]

    def pooled_covariance(self):
        divisor = self.row_count - len(self.counts)
        return [
            [ordered_sum(scatter[a][b] for scatter in self.scatter) / divisor
             for b in range(self.feature_count)]
            for a in range(self.feature_count)
        ]


class GaussianModel:
    def __init__(self, name, features, statistics, prior_mode, epsilon, gamma):
        self.name = name
        self.features = tuple(features)
        self.statistics = statistics
        self.means = statistics.means
        self.epsilon = epsilon
        self.gamma = gamma
        class_count = len(statistics.counts)
        if prior_mode == "empirical":
            self.priors = [count / statistics.row_count for count in statistics.counts]
        else:
            self.priors = [1 / class_count] * class_count
        self.max_variance = max(statistics.variances)
        self.added_variance = epsilon * self.max_variance
        self.covariances = []
        if name == "LDA":
            pooled = statistics.pooled_covariance()
            self.covariances = [pooled] * class_count
        else:
            for count, scatter in zip(statistics.counts, statistics.scatter):
                covariance = zeros(len(features))
                for a in range(len(features)):
                    for b in range(len(features)):
                        if name == "NB":
                            if a == b:
                                covariance[a][b] = scatter[a][b] / count + self.added_variance
                        else:
                            value = scatter[a][b] / (count - 1)
                            covariance[a][b] = value if a == b else value * (1 - gamma)
                self.covariances.append(covariance)
        if name == "LDA":
            lower = cholesky(self.covariances[0])
            self.factors = [lower] * class_count
            self.log_determinants = [log_determinant(lower)] * class_count
        else:
            self.factors = [cholesky(matrix) for matrix in self.covariances]
            self.log_determinants = [log_determinant(lower) for lower in self.factors]
        self.log_priors = [log(prior) for prior in self.priors]
        self.normalizer = len(features) * log(2 * pi) / 2

    def vector(self, values):
        return [values[j] for j in self.features]

    def squared_distances(self, vector):
        return [
            quadratic_form(lower, [value - center for value, center in zip(vector, mean)])
            for lower, mean in zip(self.factors, self.means)
        ]

    def distances(self, values):
        return self.squared_distances(self.vector(values))

    def scores(self, vector):
        distances = self.squared_distances(vector)
        return [
            prior - self.normalizer - determinant / 2 - distance / 2
            for prior, determinant, distance in zip(
                self.log_priors, self.log_determinants, distances
            )
        ]

    def predict_vector(self, vector):
        return argmax(self.scores(vector))

    def predict(self, values):
        return self.predict_vector(self.vector(values))

    def infer_vector(self, vector, costs=None):
        scores = self.scores(vector)
        predicted = argmax(scores)
        maximum = scores[predicted]
        exponentials = [exp(score - maximum) for score in scores]
        total = ordered_sum(exponentials)
        probabilities = [value / total for value in exponentials]
        log_total = log(total)
        log_probabilities = [(score - maximum) - log_total for score in scores]
        decision = predicted
        if costs is not None:
            risks = [
                ordered_sum(probabilities[k] * costs[k][b] for k in range(len(scores)))
                for b in range(len(scores))
            ]
            decision = argmin(risks)
        return Prediction(
            predicted, probabilities, log_probabilities, max(probabilities), decision
        )

    def infer(self, values, costs=None):
        return self.infer_vector(self.vector(values), costs)


def train_model(rows, features, class_count, name, prior_mode, epsilon, gamma):
    statistics = Statistics(rows, features, class_count)
    return GaussianModel(name, features, statistics, prior_mode, epsilon, gamma)

from math import log, sqrt


def ordered_sum(values):
    total = 0.0
    for value in values:
        total += value
    return total


def dot(left, right):
    return ordered_sum(a * b for a, b in zip(left, right))


def zeros(size):
    return [[0.0] * size for _ in range(size)]


def cholesky(matrix):
    size = len(matrix)
    lower = zeros(size)
    for i in range(size):
        for j in range(i + 1):
            subtotal = ordered_sum(lower[i][k] * lower[j][k] for k in range(j))
            remainder = matrix[i][j] - subtotal
            if i == j:
                lower[i][i] = sqrt(remainder)
            else:
                lower[i][j] = remainder / lower[j][j]
    return lower


def forward(lower, right):
    result = [0.0] * len(lower)
    for i in range(len(lower)):
        subtotal = ordered_sum(lower[i][k] * result[k] for k in range(i))
        result[i] = (right[i] - subtotal) / lower[i][i]
    return result


def backward(lower, right):
    size = len(lower)
    result = [0.0] * size
    for i in range(size - 1, -1, -1):
        subtotal = ordered_sum(lower[k][i] * result[k] for k in range(i + 1, size))
        result[i] = (right[i] - subtotal) / lower[i][i]
    return result


def log_determinant(lower):
    return 2 * ordered_sum(log(lower[i][i]) for i in range(len(lower)))


def quadratic_form(lower, difference):
    transformed = forward(lower, difference)
    return dot(transformed, transformed)


def jacobi(matrix):
    size = len(matrix)
    current = [row[:] for row in matrix]
    vectors = zeros(size)
    for i in range(size):
        vectors[i][i] = 1.0
    sweeps = 0
    while True:
        off = sqrt(ordered_sum(
            current[a][b] * current[a][b]
            for a in range(size - 1)
            for b in range(a + 1, size)
        ))
        if off < 0.000000000001 or sweeps == 50:
            break
        for a in range(size - 1):
            for b in range(a + 1, size):
                if current[a][b] == 0:
                    continue
                theta = (current[b][b] - current[a][a]) / (2 * current[a][b])
                sign = 1 if theta >= 0 else -1
                tangent = sign / (abs(theta) + sqrt(theta * theta + 1))
                cosine = 1 / sqrt(tangent * tangent + 1)
                sine = tangent * cosine
                for k in range(size):
                    if k == a or k == b:
                        continue
                    x, y = current[k][a], current[k][b]
                    current[k][a] = current[a][k] = cosine * x - sine * y
                    current[k][b] = current[b][k] = sine * x + cosine * y
                off_diagonal = current[a][b]
                current[a][a] = current[a][a] - tangent * off_diagonal
                current[b][b] = current[b][b] + tangent * off_diagonal
                current[a][b] = current[b][a] = 0.0
                for k in range(size):
                    x, y = vectors[k][a], vectors[k][b]
                    vectors[k][a] = cosine * x - sine * y
                    vectors[k][b] = sine * x + cosine * y
        sweeps += 1
    return [current[i][i] for i in range(size)], vectors, sweeps

from math import floor
from pathlib import Path

from evaluation import reduced_fraction


def real(value):
    result = f"{value:.4f}"
    return "0.0000" if result == "-0.0000" else result


def reals(values):
    return " ".join(real(value) for value in values)


def fraction_text(value):
    if value is None:
        return "-"
    numerator, denominator = value
    return f"{numerator}/{denominator} {real(numerator / denominator)}"


def ratio_text(numerator, denominator):
    return fraction_text(reduced_fraction(numerator, denominator))


def frame(grid):
    border = "+" + "-" * len(grid[0]) + "+"
    return [border, *("|" + "".join(row) + "|" for row in grid), border]


def cell(value, low, high, size):
    return floor((value - low) / (high - low) * (size - 1) + 0.5)


def join_sections(sections):
    lines = []
    for section in sections:
        if lines:
            lines.append("")
        lines.extend(section)
    return lines


def write_lines(path, lines):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="ascii", newline="\n") as destination:
        for line in lines:
            destination.write(line + "\n")
